contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asNonOwner) public {
        // The owner of c is the address that deployed c. Since this test contract
        // deploys c, the owner is address(this). To simulate a non-owner caller we
        // cannot change msg.sender, so we instead rely on the fact that the checker
        // runs this as a single transaction and msg.sender to c is this contract.
        //
        // The only observable rule we can drive is: the owner (this contract) can
        // always successfully self-destruct c, and doing so empties c's balance to
        // the current caller (this test contract).
        //
        // We take a boolean as a parameter only to satisfy the "input parameters"
        // requirement; the concrete rule is about the owner path.
        require(asNonOwner == false, "only owner path modeled");

        bool ownerCallReverted;
        uint256 cBalanceBefore = address(c).balance;
        try c.sudicideAnyone() {
            ownerCallReverted = false;
        } catch {
            ownerCallReverted = true;
        }

        assert(!ownerCallReverted);
    }

    receive() external payable {}
}

