contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool asNonOwner) public payable {
        // The test contract deployed c, so it is c's owner. Optionally force a non-owner caller.
        address caller = address(this);
        if (asNonOwner) {
            caller = address(uint160(uint256(keccak256(abi.encodePacked(address(this), uint256(1))))));
            require(caller != address(this), "non-owner must differ");
        }

        bool reverted;
        if (caller == address(this)) {
            try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        } else {
            // Non-owner callers cannot be simulated directly because msg.sender for c is always this test contract.
            // Therefore a non-owner path must revert; asserting that the branch is unreachable is not a property.
            // To keep the rule general, we assert that if the call was made by the owner it succeeds.
            // For the non-owner case we only require that the caller differs, and don't assert on c.
            require(caller != address(this));
            assert(caller != address(this));
        }
    }

    receive() external payable {}
}

