contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        bool reverted;
        uint balBefore = address(c).balance;
        uint codeBefore = address(c).code.length;
        uint callerBalBefore = caller.balance;

        // Impersonate the untrusted caller by sending the call from this test contract.
        // The test contract is NOT the deployer/owner of c (c was deployed in the test's constructor,
        // so msg.sender for c is this test contract, not `caller`).
        // To exercise the non-owner path, we require that the caller is not this contract's owner-like caller.
        // In this harness msg.sender to c is always this test contract, so any call is a non-owner call
        // unless the test contract itself is the owner. The owner is set in c's constructor to the deployer,
        // which is this test contract. To test the non-owner path we submit from a different caller by
        // checking that caller != address(this).
        require(caller != address(this));

        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint codeAfter = address(c).code.length;
        uint callerBalAfter = caller.balance;

        assert(reverted && balAfter == balBefore && codeAfter == codeBefore && callerBalAfter == callerBalBefore);
    }

    receive() external payable {}
}

