contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(address(this).balance >= 0);

        // first call: owner selfdestructs c
        c.sudicideAnyone();

        // record balance after destruction
        uint256 beforeBalance = address(c).balance;

        // second call: must still go through (no code) and not revert
        c.sudicideAnyone();

        assert(address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address nonOwner;

    constructor(C _c) {
        c = _c;
        nonOwner = address(0xdeadbeef);
    }

    function run(address caller) public payable {
        require(caller != address(this), "caller must not be owner");
        require(address(this).balance >= 0);

        // record c's Ether balance before the call
        uint256 beforeBalance = address(c).balance;

        // attempt to call sudicideAnyone from a non-owner caller
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // rule: a non-owner call must revert and must not change c's balance
        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

